tity":"","not_null":true,"generated":""},{"name":"applied_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""},{"name":"originating_transport_attempt_id","type":"uuid","default":null,"identity":"","not_null":false,"generated":""}],"indexes":[{"name":"z02_core_applications_pkey","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX z02_core_applications_pkey ON gridex_received_sources.z02_core_applications USING btree (source_message_id, request_id)"},{"name":"z02_core_applications_source_message_id_object_id_identity__key","ready":true,"valid":true,"definition":"CREATE UNIQUE INDEX z02_core_applications_source_message_id_object_id_identity__key ON gridex_received_sources.z02_core_applications USING btree (source_message_id, object_id, identity_agency)"}],"options":null,"policies":[{"name":"z02_core_application_service_read","check":null,"roles":["service_role"],"using":"true","command":"r","permissive":true}],"triggers":[{"name":"expectation_z02_applied","enabled":"O","definition":"CREATE TRIGGER expectation_z02_applied AFTER INSERT ON gridex_received_sources.z02_core_applications FOR EACH ROW EXECUTE FUNCTION gridex_business_expectations.applied_source_v1()"},{"name":"z02_core_applications_no_mutation","enabled":"O","definition":"CREATE TRIGGER z02_core_applications_no_mutation BEFORE DELETE OR UPDATE ON gridex_received_sources.z02_core_applications FOR EACH ROW EXECUTE FUNCTION gridex_received_sources.reject_mutation()"},{"name":"z02_core_applications_no_truncate","enabled":"O","definition":"CREATE TRIGGER z02_core_applications_no_truncate BEFORE TRUNCATE ON gridex_received_sources.z02_core_applications FOR EACH STATEMENT EXECUTE FUNCTION gridex_received_sources.reject_mutation()"}],"force_rls":true,"constraints":[{"name":"z02_core_applications_canonical_assessment_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (canonical_assessment_id) REFERENCES gridex_received_sources.validation_assessments(id) ON DELETE RESTRICT"},{"name":"z02_core_applications_environment_check","type":"c","validated":true,"definition":"CHECK (environment = ANY (ARRAY[''test''::text, ''production''::text]))"},{"name":"z02_core_applications_originating_transport_attempt_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (originating_transport_attempt_id) REFERENCES gridex_ediel_transport.attempts(id) ON DELETE RESTRICT"},{"name":"z02_core_applications_pkey","type":"p","validated":true,"definition":"PRIMARY KEY (source_message_id, request_id)"},{"name":"z02_core_applications_source_message_id_fkey","type":"f","validated":true,"definition":"FOREIGN KEY (source_message_id) REFERENCES gridex_received_sources.sources(source_message_id) ON DELETE RESTRICT"},{"name":"z02_core_applications_source_message_id_object_id_identity__key","type":"u","validated":true,"definition":"UNIQUE (source_message_id, object_id, identity_agency)"},{"name":"z02_core_applications_source_payload_hash_check","type":"c","validated":true,"definition":"CHECK (source_payload_hash ~ ''^[a-f0-9]{64}$''::text)"}]}'::jsonb;
 required jsonb; expected_column jsonb; actual jsonb; expected_value jsonb;
 before_function pg_catalog.pg_proc%rowtype; after_function pg_catalog.pg_proc%rowtype;
 delegate pg_catalog.pg_proc%rowtype; definition text; relation_name text; target oid;
BEGIN
 FOR required IN SELECT value FROM jsonb_array_elements(prerequisites) LOOP
  IF NOT coalesce(required->'body_md5s' ? (SELECT md5(prosrc) FROM pg_catalog.pg_proc
    WHERE oid=to_regprocedure(required->>'signature')),false) THEN
   RAISE EXCEPTION 'extra_z02_exact_dependency_required: %',required->>'signature';END IF;
 END LOOP;
 FOR relation_name IN SELECT jsonb_array_elements_text(relations) LOOP
  IF to_regclass(relation_name) IS NULL THEN RAISE EXCEPTION 'extra_z02_relation_required: %',relation_name;END IF;
 END LOOP;
 target:=to_regclass(receipt->>'name');
 -- Source-owned append-only outcome shape and effects are required before a
 -- wrapper can report success. Merely finding a same-name table is insufficient.
 FOR expected_column IN SELECT value FROM jsonb_array_elements(receipt->'columns') LOOP
  SELECT jsonb_build_object('name',a.attname,'type',a.atttypid::regtype::text,
   'not_null',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,
   'default',pg_get_expr(d.adbin,d.adrelid)) INTO actual FROM pg_catalog.pg_attribute a
   LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=target AND a.attname=expected_column->>'name' AND NOT a.attisdropped;
  IF actual IS DISTINCT FROM expected_column THEN
   RAISE EXCEPTION 'extra_z02_receipt_column_changed: %',expected_column->>'name';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,
  'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated) ORDER BY c.conname),'[]'::jsonb)
 INTO actual FROM pg_catalog.pg_constraint c WHERE c.conrelid=target;
 SELECT jsonb_agg(value ORDER BY value->>'name') INTO expected_value FROM jsonb_array_elements(receipt->'constraints');
 IF actual IS DISTINCT FROM expected_value THEN RAISE EXCEPTION 'extra_z02_receipt_constraints_changed';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,
  'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname),'[]'::jsonb)
 INTO actual FROM pg_catalog.pg_trigger t WHERE t.tgrelid=target AND NOT t.tgisinternal;
 SELECT jsonb_agg(value ORDER BY value->>'name') INTO expected_value FROM jsonb_array_elements(receipt->'triggers');
 IF actual IS DISTINCT FROM expected_value THEN RAISE EXCEPTION 'extra_z02_receipt_trigger_effects_changed';END IF;
 IF NOT EXISTS(SELECT FROM pg_catalog.pg_class WHERE oid=target AND relrowsecurity AND relforcerowsecurity) THEN
  RAISE EXCEPTION 'extra_z02_receipt_rls_required';END IF;
 SELECT * INTO STRICT before_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
 SELECT * INTO delegate FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'alias_signature');
 IF NOT FOUND THEN
  EXECUTE spec->>'alias_definition';
  EXECUTE format('ALTER FUNCTION %s OWNER TO %I',spec->>'alias_signature',pg_get_userbyid(before_function.proowner));
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',spec->>'alias_signature');
  SELECT * INTO STRICT delegate FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'alias_signature');
 END IF;
 SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),
  'proconfig',p.proconfig,'provolatile',p.provolatile,'prosecdef',p.prosecdef,
  'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'proparallel',p.proparallel,
  'procost',p.procost,'prorows',p.prorows,'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,
  'return_type',p.prorettype::regtype::text,'proretset',p.proretset,
  'identity_arguments',pg_get_function_identity_arguments(p.oid),
  'arguments',pg_get_function_arguments(p.oid),'language',l.lanname)
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=delegate.oid;
 expected_value:=((spec->'expected')-'acl')||jsonb_build_object(
  'owner',pg_get_userbyid(before_function.proowner),'proconfig',jsonb_build_array('search_path=pg_catalog'));
 IF md5(delegate.prosrc) IS DISTINCT FROM spec->>'alias_body_md5'
  OR actual IS DISTINCT FROM expected_value
  OR EXISTS(SELECT FROM aclexplode(coalesce(delegate.proacl,acldefault('f',delegate.proowner)))
    WHERE grantee<>delegate.proowner) THEN
  RAISE EXCEPTION 'extra_z02_source_delegate_body_or_all_attributes_or_owner_only_policy_changed';END IF;
 IF md5(before_function.prosrc)=spec->>'after' OR md5(before_function.prosrc)=spec->>'canonical_complete' THEN
  RETURN; -- Source-complete/replay preserves its complete existing identity.
 END IF;
 SELECT jsonb_build_object('owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,
  'proconfig',p.proconfig,'provolatile',p.provolatile,'prosecdef',p.prosecdef,
  'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'proparallel',p.proparallel,
  'procost',p.procost,'prorows',p.prorows,'proargnames',p.proargnames,'proargmodes',p.proargmodes::text,
  'return_type',p.prorettype::regtype::text,'proretset',p.proretset,
  'identity_arguments',pg_get_function_identity_arguments(p.oid),
  'arguments',pg_get_function_arguments(p.oid),'language',l.lanname)
 INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=before_function.oid;
 IF actual IS DISTINCT FROM spec->'expected' OR md5(before_function.prosrc) IS DISTINCT FROM spec->>'before'
  OR before_function.prosrc IS DISTINCT FROM spec->>'original' THEN
  RAISE EXCEPTION 'extra_z02_public_predecessor_changed_requires_review';END IF;
 definition:=pg_get_functiondef(before_function.oid);
 IF strpos(definition,spec->>'original')=0 THEN RAISE EXCEPTION 'extra_z02_exact_original_body_required';END IF;
 EXECUTE replace(definition,spec->>'original',spec->>'patched');
 SELECT * INTO STRICT after_function FROM pg_catalog.pg_proc WHERE oid=to_regprocedure(spec->>'signature');
 IF (to_jsonb(after_function)-'prosrc') IS DISTINCT FROM (to_jsonb(before_function)-'prosrc')
  OR md5(after_function.prosrc) IS DISTINCT FROM spec->>'after' THEN
  RAISE EXCEPTION 'extra_z02_all_public_identity_attributes_must_remain_exact';END IF;
END
$extra_z02$;
NOTIFY pgrst,'reload schema';
COMMIT;
